136. // Memory Region
137. //==================================================================================================
138. 
139. ///
140. /// # Description
141. ///
142. /// A memory region.
143. ///
144. #[verus_verify(external_derive)]
145. #[derive(Debug, Clone)]
146. pub struct MemoryRegion<T: Address> {
147.     name: String,
148.     start: T,
149.     size: usize,
150.     typ: MemoryRegionType,
151.     perm: AccessPermission,
152.     cache_policy: Option<MmioCachePolicy>,
153. }
154. 
155. impl<T: Address> MemoryRegion<T> {
156.     /// Maximum byte-length of a memory region name.
157.     const MEMORY_REGION_NAME_MAX: usize = 32;
158. 
159.     /// Creates a new memory region.
160.     pub fn new(
161.         name: &str,
162.         start: T,
163.         size: usize,
164.         typ: MemoryRegionType,
165.         perm: AccessPermission,
166.     ) -> Result<Self, Error> {
167.         // Check if name is too long (byte length).
168.         if name.len() > Self::MEMORY_REGION_NAME_MAX {
169.             let reason: &str = "memory region name is too long";
170.             error!("{reason} (name.len={}, NAME_MAX={})", name.len(), Self::MEMORY_REGION_NAME_MAX);
171.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
172.         }
173. 
174.         // Check if size of the memory region is valid.
175.         if size == 0 {
176.             return Err(Error::new(ErrorCode::InvalidArgument, "invalid memory region size"));
177.         }
178. 
179.         // Check if memory region is too big.
180.         let start_raw_addr: usize = start.clone().into_raw_value();
181.         let end_raw_addr: usize = match start_raw_addr.checked_add(size - 1) {
182.             Some(end_raw_addr) => end_raw_addr,
183.             None => {
184.                 return Err(Error::new(ErrorCode::TooBig, "memory region is too big"));
185.             },
186.         };
187. 
188.         // Check if memory region spans outside the address space.
189.         if end_raw_addr > T::max_addr() {
190.             return Err(Error::new(
191.                 ErrorCode::InvalidArgument,
192.                 "memory region spans outside the address space",
193.             ));
194.         }
195. 
196.         Ok(Self {
197.             name: name.to_string(),
198.             start,
199.             size,
200.             typ,
201.             perm,
202.             cache_policy: None,
203.         })
204.     }
205. 
206.     pub fn name(&self) -> String {
207.         self.name.clone()
208.     }
209. 
210.     /// Returns the first valid address that lies in the target memory region.
211.     pub fn start(&self) -> T {
212.         self.start.clone()
213.     }
214. 
215.     /// Returns the size of the target memory region.
216.     pub fn size(&self) -> usize {
217.         self.size
218.     }
219. 
220.     /// Returns the type of the target memory region.
221.     pub fn typ(&self) -> MemoryRegionType {
222.         self.typ
223.     }
224. 
225.     /// Returns the permissions of the target memory region.
226.     pub fn perm(&self) -> AccessPermission {
227.         self.perm
228.     }
229. 
230.     ///
231.     /// # Description
232.     ///
233.     /// Returns the MMIO cache policy of the target memory region, if set.
234.     ///
235.     /// # Returns
236.     ///
237.     /// The [`MmioCachePolicy`] if one was assigned, or `None` otherwise.
238.     ///
239.     pub fn cache_policy(&self) -> Option<MmioCachePolicy> {
240.         self.cache_policy
241.     }
242. 
243.     ///
244.     /// # Description
245.     ///
246.     /// Sets the MMIO cache policy of the target memory region.
247.     ///
248.     /// # Parameters
249.     ///
250.     /// - `policy`: The cache policy to assign.
251.     ///
252.     pub fn set_cache_policy(&mut self, policy: MmioCachePolicy) {
253.         self.cache_policy = Some(policy);
254.     }
255. }
256. 
257. impl<T: Address> PartialEq for MemoryRegion<T> {
258.     fn eq(&self, other: &Self) -> bool {
259.         self.name == other.name
260.             && self.start == other.start
261.             && self.size == other.size
262.             && self.typ == other.typ
263.             && self.perm == other.perm
