 #[cfg(verus_keep_ghost)]
 include!("region.proof.rs");

 use crate::hal::mem::types::{
     access::AccessPermission,
     address::{
         Address,
         PageAligned,
         PhysicalAddress,
         VirtualAddress,
     },
 };
 use ::alloc::string::{
